def to_grams(value, unit):
    conversions = {'kg': 1000, 'g': 1, 'lb': 435.592}
    return value * conversions.get(unit, 1)

files.recipe.py:
from units import to_grams


def total_grams(ingredients):
    return sum(to_grams(qty, unit) for qty, unit in ingredients)

files.shipping.py:
from units import to_grams


def shipping_cost(weight_value, weight_unit, rate_per_kg=2.5):
    grams = to_grams(weight_value, weight_unit)
    kg = grams / 1000
    return round(kg * rate_per_kg, 2)

